package solution

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"time"
)

type Release struct {
	ID        int
	Name      string
	Published time.Time
}

type ReleasePage struct {
	Items      []Release
	NextCursor int
}

type releaseWire struct {
	ID        *int    `json:"id"`
	Name      *string `json:"name"`
	Published *string `json:"published"`
}

type releasePageWire struct {
	Items      *[]releaseWire `json:"items"`
	NextCursor *int           `json:"next_cursor"`
}

func DecodeReleasePage(data []byte) (ReleasePage, error) {
	var wire releasePageWire
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&wire); err != nil {
		return ReleasePage{}, fmt.Errorf("decode release page: %w", err)
	}
	if err := decoder.Decode(&struct{}{}); err != io.EOF {
		if err == nil {
			err = fmt.Errorf("trailing JSON value")
		}
		return ReleasePage{}, fmt.Errorf("decode release page: %w", err)
	}
	if wire.Items == nil || wire.NextCursor == nil {
		return ReleasePage{}, fmt.Errorf("items and next_cursor are required and cannot be null")
	}
	if *wire.NextCursor < 0 {
		return ReleasePage{}, fmt.Errorf("next_cursor cannot be negative")
	}
	items := make([]Release, 0, len(*wire.Items))
	seen := make(map[int]struct{}, len(*wire.Items))
	for index, item := range *wire.Items {
		if item.ID == nil || item.Name == nil || item.Published == nil {
			return ReleasePage{}, fmt.Errorf("item %d has a missing or null field", index)
		}
		if *item.ID <= 0 || *item.Name == "" {
			return ReleasePage{}, fmt.Errorf("item %d has an invalid id or name", index)
		}
		if _, exists := seen[*item.ID]; exists {
			return ReleasePage{}, fmt.Errorf("duplicate id %d", *item.ID)
		}
		published, err := time.Parse("2006-01-02", *item.Published)
		if err != nil || published.Format("2006-01-02") != *item.Published {
			return ReleasePage{}, fmt.Errorf("item %d has an invalid publication date", index)
		}
		seen[*item.ID] = struct{}{}
		items = append(items, Release{ID: *item.ID, Name: *item.Name, Published: published})
	}
	return ReleasePage{Items: items, NextCursor: *wire.NextCursor}, nil
}

